-- Requires local migrated schema + prepared archive fixture. All mutations roll back.
begin;
do $test$
declare u uuid;a uuid;v uuid;d date;job jsonb;old_job jsonb;other_job jsonb;expected_metrics jsonb;rules_config jsonb;old_request jsonb;before_hash text;history_count bigint;ver integer;cutoff date;
begin
 select id into u from auth.users where email='owner@test.com';perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('app.ctx_ready','0',true);
 a:=public.get_active_account_id();v:=public.get_active_venue_id();perform set_config('test.additional_venue',v::text,true);perform set_config('test.additional_owner',u::text,true);
 select md5(jsonb_build_object('transactions',(select jsonb_agg(to_jsonb(t) order by id) from public.transactions t),'accruals',(select jsonb_agg(to_jsonb(t) order by id) from public.payroll_accruals t),'adjustments',(select jsonb_agg(to_jsonb(t) order by id) from public.payroll_adjustments t),'banks',(select jsonb_agg(to_jsonb(t) order by id) from public.bank_accounts t))::text) into before_hash;
 select r.config into rules_config from public.sales_additional_rules r where venue_id=v order by valid_from desc limit 1;
 if rules_config is null then raise exception 'Load prepared archive fixture first';end if;
 begin perform private.sales_validate_additional_rules(jsonb_set(rules_config,'{tiers}', '[{"rate":150}]'));raise exception 'Missing tier threshold accepted';exception when raise_exception then if sqlerrm<>'Некорректная шкала баллов' then raise;end if;end;
 delete from public.sales_additional_history where venue_id=v;delete from public.sales_additional_reports where venue_id=v;
 select ((now() at time zone timezone)-make_interval(hours=>day_start_hour))::date into cutoff from public.sales_settings where venue_id=v;
 d:=cutoff-1;
 if private.sales_request_additional_day(v,d,false)<>2 or private.sales_request_additional_day(v,d,false)<>0 or private.sales_request_additional_day(v,cutoff,false)<>0 then raise exception 'Open day/dedup failed';end if;
 job:=public.sales_claim_additional_report(v);old_job:=job;
 expected_metrics:=jsonb_build_object('revenue',0,'primeCost',0,'bonus',0,'points',case when job->>'kind'='bar' then null else 0 end,'quantities',(select jsonb_object_agg(g->>'id','null'::jsonb) from jsonb_array_elements(rules_config->(job->>'kind')) g));
 if public.sales_commit_additional_report((job->>'id')::uuid,gen_random_uuid(),expected_metrics) then raise exception 'Foreign lease accepted';end if;
 begin perform public.sales_commit_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,expected_metrics||'{"quantities":{}}');raise exception 'Partial report accepted';exception when raise_exception then if sqlerrm<>'Неполный набор групп допродаж' then raise;end if;end;
 if not public.sales_commit_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,expected_metrics) then raise exception 'Commit failed';end if;
 select count(*) into history_count from public.sales_additional_history;
 if not public.sales_commit_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,expected_metrics) or (select count(*) from public.sales_additional_history)<>history_count then raise exception 'Lost response duplicated history';end if;
 perform public.sales_fail_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,'Lost response',null);
 if not exists(select 1 from public.sales_additional_reports where id=(job->>'id')::uuid and state='ready') then raise exception 'Ready report reopened';end if;
 perform private.sales_request_additional_day(v,d,true);job:=public.sales_claim_additional_report(v);
 update public.sales_additional_reports set next_retry_at=now()+interval '1 hour' where venue_id=v and id<>(job->>'id')::uuid;
 update public.sales_additional_reports set claimed_at=now()-interval '4 minutes' where id=(job->>'id')::uuid;
 other_job:=public.sales_claim_additional_report(v);
 if other_job->>'id'<>job->>'id' or other_job->>'lease_token'=job->>'lease_token' then raise exception 'Expired lease not reclaimed';end if;
 if public.sales_commit_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,expected_metrics) then raise exception 'Stale worker accepted';end if;
 perform public.sales_fail_additional_report((other_job->>'id')::uuid,(other_job->>'lease_token')::uuid,'Provider unavailable',null);
 if not exists(select 1 from public.sales_additional_reports where id=(old_job->>'id')::uuid and metrics=expected_metrics and metrics_request=old_job->'request') then raise exception 'Good metrics/rule snapshot lost';end if;
 perform private.sales_request_additional_day(v,d,true);job:=public.sales_claim_additional_report(v);
 update public.sales_additional_sources set version=version+1 where venue_id=v;
 if public.sales_commit_additional_report((job->>'id')::uuid,(job->>'lease_token')::uuid,expected_metrics) then raise exception 'Changed source accepted';end if;
 select version into ver from public.sales_additional_sources where venue_id=v;
 begin perform public.sales_save_additional_rules(v,ver,cutoff,rules_config,'Test');raise exception 'Historical rule accepted';exception when raise_exception then if sqlerrm not like 'Новые правила%' then raise;end if;end;
 begin perform public.sales_save_additional_rules(gen_random_uuid(),ver,cutoff+1,rules_config,'Test');raise exception 'Foreign venue accepted';exception when raise_exception then if sqlerrm not like 'Заведение изменилось%' then raise;end if;end;
 perform public.sales_save_additional_rules(v,ver,cutoff+1,rules_config,'Test future version');
 begin perform public.sales_save_additional_rules(v,ver,cutoff+1,rules_config,'Stale editor');raise exception 'Stale editor accepted';exception when raise_exception then if sqlerrm not like 'Правила изменились%' then raise;end if;end;
 if has_function_privilege('authenticated','public.sales_claim_additional_report(uuid)','EXECUTE') or has_table_privilege('authenticated','public.sales_additional_reports','UPDATE') or has_function_privilege('anon','public.sales_request_additional_month(date,uuid)','EXECUTE') then raise exception 'Unsafe worker grants';end if;
 if before_hash is distinct from md5(jsonb_build_object('transactions',(select jsonb_agg(to_jsonb(t) order by id) from public.transactions t),'accruals',(select jsonb_agg(to_jsonb(t) order by id) from public.payroll_accruals t),'adjustments',(select jsonb_agg(to_jsonb(t) order by id) from public.payroll_adjustments t),'banks',(select jsonb_agg(to_jsonb(t) order by id) from public.bank_accounts t))::text) then raise exception 'Financial/payroll mutation';end if;
 raise notice 'PASS: date/scope/dedup, closed working day, complete results, leases/reclaim, atomic replay, immutable good metrics/rules, future rules, stale editor, worker grants and unchanged finance/payroll';
end $test$;
set local role authenticated;
do $$ begin if exists(select 1 from public.sales_additional_archive where venue_id<>current_setting('test.additional_venue')::uuid) then raise exception 'Foreign archive leak';end if;end $$;
select set_config('request.jwt.claim.sub','',true),set_config('app.ctx_ready','0',true);
do $$ begin if exists(select 1 from public.sales_additional_archive) or exists(select 1 from public.sales_additional_rules) or exists(select 1 from public.sales_additional_reports) then raise exception 'Anonymous leak';end if;end $$;
rollback;
